package app.devlens;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;
public class ReminderReceiver extends BroadcastReceiver{
 static PendingIntent intent(Context c,int id){return PendingIntent.getBroadcast(c,id,new Intent(c,ReminderReceiver.class).setAction("remind").putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,JSONObject p)throws Exception{long at=p.getLong("at");if(at<=System.currentTimeMillis())throw new Exception("Выберите время в будущем");int id=p.getInt("id");c.getSharedPreferences("reminders",0).edit().putString(""+id,p.toString()).commit();((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,intent(c,id));}
 static void cancel(Context c,int id){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(intent(c,id));c.getSharedPreferences("reminders",0).edit().remove(""+id).commit();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(id);}
 @Override public void onReceive(Context c,Intent i){try{if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())){for(Object raw:c.getSharedPreferences("reminders",0).getAll().values()){JSONObject p=new JSONObject(raw.toString());if(p.getLong("at")<System.currentTimeMillis())p.put("at",System.currentTimeMillis()+60000);schedule(c,p);}return;}int id=i.getIntExtra("id",0);String raw=c.getSharedPreferences("reminders",0).getString(""+id,"");if(raw.isEmpty())return;JSONObject p=new JSONObject(raw);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("reminders","Напоминания",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);nm.notify(id,new Notification.Builder(c,"reminders").setSmallIcon(R.drawable.icon).setContentTitle("DevLens · Напоминание").setContentText(p.getString("text")).setStyle(new Notification.BigTextStyle().bigText(p.getString("text"))).setContentIntent(open).setAutoCancel(true).build());long interval=p.optLong("interval",0);if(interval>0){p.put("at",System.currentTimeMillis()+interval);schedule(c,p);}else c.getSharedPreferences("reminders",0).edit().remove(""+id).commit();}catch(Exception e){android.util.Log.e("DevLens","Reminder failed",e);}}
}
